#pragma once
inline void runTiming525Checks(){
 using namespace MidiTools522;auto require=[](bool ok,const char* text){if(!ok)throw std::runtime_error(text);};
 State s;s.values["mainLow"]=-1;s.values["mainHigh"]=1;s.values["mainRange"]=24;s.values["fillRange"]=24;s.values["rootAmount"]=38;s.values["firstRoot"]=84;s.enabled.fill(true);s.main.fill(50);s.fill.fill(50);Random random(15);
 for(int i=0;i<100;++i)require(registerPitch(s,0,false,random)==36,"octave probability zero prefers base");
 s.values["mainOctaveProbability"]=100;for(int i=0;i<100;++i){int note=registerPitch(s,0,false,random);require((note==24||note==48)&&note%12==0,"octave probability 100 selects other legal register");}
 s.values["mainOctaveProbability"]=50;int jumped=0;for(int i=0;i<1000;++i)jumped+=registerPitch(s,0,false,random)!=36;require(jumped>350&&jumped<650,"octave probability intermediate distribution");
 s.values["mainRange"]=0;for(int i=0;i<20;++i)require(registerPitch(s,0,false,random)==36,"octave constraints override impossible jump");
 s.values["mainRange"]=36;s.values["mainLow"]=1;s.values["mainHigh"]=2;s.values["mainOctaveProbability"]=0;require(registerPitch(s,0,false,random)==48,"closest allowed octave when base excluded");
 s.values["mainLow"]=0;s.values["mainHigh"]=1;s.values["mainOctaveProbability"]=0;s.values["fillOctaveProbability"]=100;require(registerPitch(s,0,false,random)==36&&registerPitch(s,0,true,random)==48,"Main and Fill octave probabilities independent");
 std::vector<PhraseNote524> sparse;for(int i=0;i<4;++i)sparse.push_back({(double)i,.25,.2,36+i,100});auto original=sparse;s.values["avoidBeats"]=0;avoidBeats525(sparse,s,0,0,4,7);for(int i=0;i<4;++i)require(sparse[i].beat==original[i].beat,"avoid zero exact bypass");
 s.values["avoidBeats"]=100;avoidBeats525(sparse,s,0,0,4,7);for(int i=0;i<4;++i){auto n=sparse[i];require(std::abs(n.beat-std::round(n.beat))>1e-7,"avoid 100 moves whole beats where space allows");require(n.allocated==original[i].allocated&&n.length==original[i].length&&n.pitch==original[i].pitch,"avoid preserves duration, Gate and pitch order");require(n.beat>=0&&n.beat+n.allocated<=4+1e-7,"avoid respects loop");if(i)require(sparse[i-1].beat+sparse[i-1].allocated<=n.beat+1e-7,"avoid stays mono");}
 double lowHits=0,highHits=0;for(int seed=1;seed<=128;++seed){auto copy=original;s.values["avoidBeats"]=25;avoidBeats525(copy,s,0,0,4,seed);for(auto n:copy)lowHits+=std::abs(n.beat-std::round(n.beat))<1e-7;copy=original;s.values["avoidBeats"]=75;avoidBeats525(copy,s,0,0,4,seed);for(auto n:copy)highHits+=std::abs(n.beat-std::round(n.beat))<1e-7;}require(highHits<lowHits,"increasing Avoid Beats reduces whole-beat probability");s.values["avoidBeats"]=100;
 std::vector<PhraseNote524> cluster;for(int i=0;i<8;++i)cluster.push_back({i*.25,.25,.2,36,100});avoidBeats525(cluster,s,0,0,4,7);for(auto n:cluster)require(std::abs(n.beat-std::round(n.beat))>1e-7,"avoid can move a packed group into later rests");
 std::vector<PhraseNote524> full;for(int i=0;i<16;++i)full.push_back({i*.25,.25,.2,36,100});avoidBeats525(full,s,0,0,4,9);require(full.size()==16,"avoid does not delete full-density notes");for(int i=0;i<16;++i)require(full[i].beat==i*.25,"avoid retains valid placement without free space");
 auto shifted=original;avoidBeats525(shifted,s,.5,0,4,7);for(int i=0;i<4;++i)require(shifted[i].beat==original[i].beat,"avoid uses absolute whole beats, not loop origin");
 auto onBeat=original;for(auto& n:onBeat)n.beat+=.5;avoidBeats525(onBeat,s,.5,0,4,7);for(auto n:onBeat)require(std::abs(n.beat+.5-std::round(n.beat+.5))>1e-7,"avoid respects absolute beat positions with offsets");
 s.values["mainRange"]=24;s.values["mainLow"]=0;s.values["mainHigh"]=1;s.values["mainOctaveProbability"]=57;s.values["gateRandom"]=20;s.values["velocityRandom"]=20;s.values["density"]=50;SequenceClip loop;loop.setLoop(.5,16.5);auto result=run(loop,s,Action::generate);
 auto phrase=[&](int part){std::vector<SequenceNote> out;double begin=loop.loopStart+part*4;for(auto n:result.notes)if(n.beat>=begin&&n.beat<begin+4){n.beat-=begin;out.push_back(n);}return out;};auto a=phrase(0);for(int part=1;part<4;++part){auto b=phrase(part);require(a.size()==b.size(),"neutral octave/avoid repetition count");for(int i=0;i<(int)a.size();++i)require(a[i].pitch==b[i].pitch&&a[i].velocity==b[i].velocity&&std::abs(a[i].beat-b[i].beat)<1e-7&&a[i].length==b[i].length,"neutral A/B shares octave and avoidance decisions");}
 s.values["avoidBeats"]=0;s.values["gateRandom"]=0;s.values["velocityRandom"]=0;s.values["gate"]=100;s.values["density"]=70;s.values["rootAmount"]=100;s.values["mainOctaveProbability"]=0;s.values["fillOctaveProbability"]=100;
 for(int triplet:{0,1})for(int amount:{1,17,36,67,99,100})for(double start:{0.,.5,.13}){
  s.values["triplet"]=triplet;s.values["fillAmount"]=amount;s.values["duration2"]=.75;s.values["chance2"]=30;SequenceClip clip;clip.setLoop(start,start+6.5);auto notes=run(clip,s,Action::generate);double section=start+4,span=2.5,fill=section+fillStart525(s,section,span),grid=rhythmicGrid525(s)/(double)ticks;int fillNotes=0;
  for(auto n:notes.notes){require(n.beat>=start-1e-7&&n.beat+n.length<=clip.loopEnd()+1e-7,"quantized fill within fractional loop bounds");if(n.beat>=fill-1e-7){++fillNotes;require(std::abs(n.beat/grid-std::round(n.beat/grid))<1e-6,"fill onset stays on rhythmic grid for all amounts");require(n.pitch==48,"Fill uses independent octave probability");}}
  require(fillNotes>0,"quantized fill fixture has notes");
 }
 juce::XmlElement xml("root");s.write(xml);State recalled;recalled.read(xml.getChildByName("midiTools522"));require(recalled.get("fillOctaveProbability")==100&&recalled.get("mainOctaveProbability")==0,"octave settings saved per profile");auto* saved=xml.getChildByName("midiTools522");saved->removeAttribute("mainOctaveProbability");saved->removeAttribute("fillOctaveProbability");saved->removeAttribute("avoidBeats");State legacy;legacy.read(saved);require(legacy.get("mainOctaveProbability")==0&&legacy.get("fillOctaveProbability")==0&&legacy.get("avoidBeats")==0,"legacy new-control defaults neutral");
 std::cout<<"525 passed: octave probabilities/limits, Main/Fill independence, Avoid Beats constraints and A/B repetition, straight/dotted/triplet fill grid, fractional bounds and recall\n";
}
